import {factsPage} from './facts.js';
import {cubePage,mountCube} from './cube.js';
import {isAdmin} from './admin.js';
import {adminPage,mountAdmin,checkAdmin} from './admin.js';
import {editorialImage} from './editorial.js';
import {aiReady,enableAI,disableAI,askAI,aiError} from './ai-client.js';
import {conversationReply} from './conversation.js';
import {policies,policyLinks,policyPage} from './legal.js';
import {arcade,levelMap,gamePage,mountGames,handleGameClick,handleGameInput,gamePoints,clearGames,feedback} from './games.js';
import {tracks} from './game-content.js';
import {icon3D} from './icons.js';
import {welcomeMessages} from './welcome-messages.js';
import {createChatStore,questionGuard} from './chat-store.js';
import {articles,worlds,quizzes} from './content.js';
import {sectionsFor,quizFor,codeConfig,shuffleQuestion} from './age-tools.js';
import {labs,labCards,labPage,mountLab,kenyaPage,mountKenya} from './experiences.js';
const $=s=>document.querySelector(s), esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const I=icon3D;
const SEND_PLANE=I('send','send-plane-3d');
const link=(to,label,cls='button',icon='arrow-right')=>`<a class="${cls}" href="#/${to}">${label}${icon?I(icon):''}</a>`;
const bands={'6-8':{name:'Little Explorer',description:'Short reads, simple words & big discoveries'},'9-11':{name:'Explorer',description:'Go deeper, ask why & connect ideas'},'12-14':{name:'Trailblazer',description:'Explore the science, challenge ideas & build'}};
const storageKey='zuno-preview-v1';let storageOK=true,state;
try{state=JSON.parse(localStorage.getItem(storageKey)||'{}')}catch{state={};storageOK=false}if(!state||typeof state!=='object')state={};
state={age:bands[state.age]?state.age:'9-11',read:Array.isArray(state.read)?state.read.filter(id=>articles.some(a=>a.id===id)):[],saved:Array.isArray(state.saved)?state.saved.filter(id=>articles.some(a=>a.id===id)):[],played:Array.isArray(state.played)?state.played.filter(id=>Object.keys(quizzes).includes(id)||id==='code'):[],days:state.days&&typeof state.days==='object'?state.days:{},large:state.large===true,motion:state.motion===true,theme:state.theme==='dark'?'dark':'light'};
let search='',category='all',quizState=null,codeState={steps:[],pos:20,running:false},worldCleanup=null,selectedPlanet=2,toastTimer,firstRender=true;
codeState.pos=codeConfig(state.age).size*(codeConfig(state.age).size-1);
let previousXP=0,motionObserver;
let lastSubmission={text:'',at:0};
let chatStore;try{chatStore=createChatStore({session:sessionStorage,persistent:localStorage})}catch{chatStore=createChatStore()}
let removedChat=null,chatDraft='',aiAbort=null,aiBusy=false;

const reduced=()=>state.motion||matchMedia('(prefers-reduced-motion: reduce)').matches;
const dateKey=()=>new Intl.DateTimeFormat('en-CA',{timeZone:'Africa/Nairobi'}).format(new Date());
const dayProgress=()=>Math.min(3,Array.isArray(state.days[dateKey()])?state.days[dateKey()].length:0);
const xp=()=>gamePoints()+new Set(state.read).size*10+new Set(state.played.filter(id=>id!=='code')).size*30+(state.played.includes('code')?25:0);
function persist(){try{localStorage.setItem(storageKey,JSON.stringify(state))}catch{storageOK=false;toast('Progress cannot be saved in this browser. You can keep exploring.')}}
function activity(key){const d=dateKey();if(!Array.isArray(state.days[d]))state.days[d]=[];if(!state.days[d].includes(key))state.days[d].push(key);const keys=Object.keys(state.days).sort();for(const old of keys.slice(0,-30))delete state.days[old];persist()}
function toast(text){clearTimeout(toastTimer);$('#toast').textContent=text;$('#toast').classList.add('visible');toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),3600)}
function awardRead(id){if(!state.read.includes(id)){state.read.push(id);activity('read:'+id);toast('Discovery complete! +10 curiosity points');}else toast('You’ve already discovered this one. Great to see you again!');render(false)}
function completeGame(id){const fresh=!state.played.includes(id);if(fresh)state.played.push(id);activity('play:'+id);return fresh}
const worldOf=id=>worlds.find(w=>w.id===id)||worlds[0];
const art=(id,badge='')=>`<div class="world-art">${['stories','wows'].includes(id)?`<span class="collection-art">${I(id==='stories'?'book-open':'lightbulb')}</span>`:`<img src="/assets/${worldOf(id).icon}.webp" alt="" loading="lazy" width="90" height="90">` }${badge?`<span class="badge">${badge}</span>`:''}</div>`;
const section=(title,to,label='See all')=>`<div class="section-head"><h2>${title}</h2>${to?link(to,label,'text-link'):''}</div>`;
function worldCard(w){return `<a class="world-card ${w.color}" href="#/discover?category=${w.id}">${editorialImage({category:w.id,id:w.id})}<div class="world-info"><h3>${w.name}</h3><p>${w.sub}</p><span class="mini-meta">${I('book-open')}${articles.filter(a=>a.category===w.id).length} ${articles.filter(a=>a.category===w.id).length===1?'discovery':'discoveries'} ${I('arrow-right')}</span></div></a>`}
function articleCard(a){return `<a href="#/discover/${a.id}" class="article-card ${worldOf(a.category).color}">${editorialImage(a)}<div class="article-body"><span class="label">${a.tag}</span><h3>${a.title}</h3><p>${a.fact}</p><div class="article-meta">${I('book-open')}${a.kind==='wow'?'A little wow':a.minutes+' min '+(a.kind==='story'?'story':'read')} <span>·</span> ${state.read.includes(a.id)?'Discovered':bands[state.age].name}</div></div></a>`}
const navItems=[['discover','compass','Discover'],['ask','message-circle','Zuno AI'],['explore','orbit','Explore Worlds'],['play','gamepad-2','Play & Learn'],['universe','star','My Universe']];
function shell(content,active){const age=bands[state.age];return `<div class="shell"><aside class="sidebar"><a href="#/discover" class="brand" aria-label="ZUNO KIDS Discover"><img class="brand-lockup" src="/assets/zuno-logo-${state.theme}-compact.webp" alt="ZUNO KIDS"><img class="brand-mini" src="/assets/zuno-icon.webp" alt=""></a><nav class="nav" aria-label="Main navigation">${navItems.map(([id,icon,label])=>`<a href="#/${id}" ${active===id?'aria-current="page"':''} class="${active===id?'active':''}">${I(icon)}<span class="nav-full">${label}</span><span class="nav-short">${({'discover':'Discover',ask:'Zuno AI',explore:'Worlds',play:'Play',universe:'My Space'}[id])}</span></a>`).join('')}</nav><div class="sidebar-note">${I('lightbulb')}<strong>Big ideas start with “why?”</strong><p>Follow your curiosity.<br>There’s a whole world waiting.</p></div><a class="parent-link" href="#/parents" aria-label="Grown-up corner">${I('shield-check')}<span>Grown-up corner</span></a></aside><div class="workspace"><header class="topbar"><a class="mobile-brand" href="#/discover" aria-label="ZUNO KIDS Discover"><img class="brand-lockup" src="/assets/zuno-logo-${state.theme}-compact.webp" alt="ZUNO KIDS"></a><div class="crumb">Your universe <span aria-hidden="true"> / </span><strong>${active==='parents'?'Grown-up corner':navItems.find(n=>n[0]===active)?.[2]||'Discover'}</strong></div><div class="top-tools"><span class="xp" aria-label="${xp()} curiosity points">${I('star')}${xp()}<span class="desktop-xp"> XP</span></span><button class="theme-button" data-action="theme" aria-label="Use ${state.theme==='light'?'dark':'light'} colours">${I(state.theme==='light'?'moon':'sun')}</button><button class="profile" data-action="age" aria-label="Reading level: ${age.name}, ages ${state.age}. Change reading level">${I('book-open')}<div class="reading-trigger-copy"><small>Reading level</small><strong><span class="desktop-band">${age.name} · </span>Ages ${state.age.replace('-','–')}</strong></div></button></div></header><main class="main" id="main" tabindex="-1">${content}<footer class="footer-note"><nav class="policy-nav" aria-label="Policies">${policyLinks()}</nav><span>Ask. Learn. Explore. &nbsp; Zuno AI, powered by ClerkOps.</span><a href="#/parents">${I('shield-check')} &nbsp; Grown-up corner · Preview</a>${location.hash==='#/discover'?`<a class="powered-by" href="https://clerkops.co.ke" target="_blank" rel="noopener noreferrer" aria-label="Powered by ClerkOps. Opens clerkops.co.ke"><span>Powered by</span><img src="/assets/clerkops-${state.theme}.webp" alt="ClerkOps" width="110" height="27"></a>`:''}</footer></main></div><button class="back-top" data-action="back-top" aria-label="Back to top">${I('arrow-left')}</button></div>`}
function intro(eyebrow,title,desc,aside=''){return `<div class="page-intro"><div><div class="eyebrow">${eyebrow}</div><h1>${title}</h1>${desc?`<p>${desc}</p>`:''}</div>${aside}</div>`}
function landing(){return `<section class="landing-hero"><div><span class="eyebrow">ASK. LEARN. EXPLORE.</span><h1>A big world.<br>A curious you.</h1><p>Stories worth sharing. Questions worth asking. Adventures that make you look a little closer.</p><div class="landing-actions">${link('discover/library','Start exploring','button lime','compass')}${link('ask','Ask Zuno AI','button light','message-circle')}</div><span class="landing-note">For curious minds aged 6–14 · Made with a little Kenyan wonder</span></div><div class="landing-collage"><img class="landing-photo" src="/assets/editorial/elephants.webp" alt="An elephant reaching for leaves in the savannah"><img class="landing-planet" src="/assets/editorial/mars.webp" alt="The surface of Mars"><img class="landing-zuno" src="/assets/zuno-cutout.webp" alt="Zuno, your learning companion"><span class="landing-sticker">A little “why?”<br>can take you far.</span></div></section>${section('Open a story. Find a new idea.','discover/library','All discoveries')}<div class="article-grid landing-reads">${articles.filter(a=>['elephants','mars','coral','rhinos'].includes(a.id)).map(articleCard).join('')}</div><section class="landing-invite"><span class="eyebrow">YOUR OWN WAY TO WONDER</span><h2>Read it. Ask it. Try it.</h2><p>Choose your reading level, explore a world, or solve a puzzle. Every little discovery counts.</p>${link('explore','Explore worlds','button','orbit')} ${link('play','Play & learn','button light','gamepad-2')}</section>`}
function home(){return intro('A little curiosity goes a long way','<span class="sr-only">What will you discover today?</span><span class="rotating-heading" aria-hidden="true" data-rotating="home">What will you discover today?</span>','A whole world of “wow” is waiting for you.',`<span class="date-pill">${I('shield-check')}A kind place to be curious</span>`)+`<div class="home-layout"><div><section class="hero"><div class="hero-copy"><div class="eyebrow">Your next big adventure</div><h2>Small explorer.<br><em>Infinite possibilities.</em></h2><p>From the stars above to the wonders of Kenya. Let’s follow your big questions.</p>${link('explore/space','Let’s explore space','button lime','rocket')}</div><div class="hero-ring" aria-hidden="true"></div><span class="hero-star" aria-hidden="true">✦</span><img class="hero-mascot" src="/assets/zuno-wave.webp" alt="Zuno, your cheerful star-antenna explorer"></section><a class="ask-strip" href="#/ask">${I('message-circle')}<span>Big questions welcome. <strong>Zuno AI</strong></span><span class="arrow home-chat-send">${SEND_PLANE}</span></a>${section('Follow your curiosity','discover/library','All discoveries') }<div class="world-grid">${worlds.slice(0,6).map(worldCard).join('')}</div>${section('Little Wows','discover/wows','More little wonders')}<div class="wow-grid home-wows">${articles.filter(a=>a.kind==='wow').slice(0,3).map(wowCard).join('')}</div>${section('Stories that spark ideas','discover/stories','Story Studio')}<a class="story-feature" href="#/discover/stories"><img src="/assets/stories-cover.webp" alt="Two curious children exploring a robot and a book"><div><span class="eyebrow">Read. Imagine. Think.</span><h3>Meet a new idea between the pages.</h3><p>Eighteen original stories, with a complete edition for your reading level.</p><span class="text-link">Choose a story ${I('arrow-right')}</span></div></a>${section(state.read.length?'Keep your curiosity going':'Your first little mission','play','Let’s play')}<a href="#/play" class="continue-card"><img src="/assets/space.webp" alt=""><div><div class="eyebrow">Read · Explore · Play</div><h3>Become a solar system explorer</h3><p>Meet the planets. Take a trip. Test your discoveries.</p></div>${I('arrow-right')}</a><section class="school-card"><div class="eyebrow">Rooted in Kenya. Ready for the world.</div><h2>Big ideas, close to home.</h2><p>Nature, people, numbers and digital skills, with familiar Kenyan examples.</p><div class="school-topics">${link('discover?category=kenya','Our Kenya','chip','globe-2')}${link('discover/fractions','Everyday maths','chip','book-open')}${link('discover/algorithms','Digital skills','chip','code-2')}</div></section></div><aside class="rail"><section class="quest-card"><div class="title-line">${I('star')}Your curiosity quest</div><p>Three little discoveries. Your own pace.</p><div class="goal-top"><span>Today’s adventure</span><span>${dayProgress()}/3</span></div><div class="progress" role="progressbar" aria-label="Today’s discoveries" aria-valuenow="${dayProgress()}" aria-valuemin="0" aria-valuemax="3"><span style="width:${dayProgress()/3*100}%"></span></div>${[['book-open','Read something new','A tiny idea can start something big.',state.days[dateKey()]?.some?.(x=>x.startsWith('read:'))],['orbit','Explore a world','Go somewhere your mind hasn’t been.',state.days[dateKey()]?.some?.(x=>x.startsWith('explore:'))],['gamepad-2','Play with an idea','Try, learn, and try again.',state.days[dateKey()]?.some?.(x=>x.startsWith('play:'))]].map(([i,t,d,done])=>`<div class="quest-line ${done?'complete':''}"><span>${I(done?'check':i)}</span><div><strong>${t}</strong><small>${d}</small></div></div>`).join('')}<a href="#/universe" class="text-link">My discoveries ${I('arrow-right')}</a></section><section class="fact-card">${I('lightbulb')}<div class="eyebrow">Wait… really?</div><p>A coral reef is built by tiny animals. Yes, animals!</p><small>There’s more beneath the surface.</small><a href="#/discover/coral" class="text-link">Dive into the story ${I('arrow-right')}</a></section><span class="rail-foot">${I('heart')}No rush. Wonder at your own pace.</span></aside></div>`}
function wowCard(a){return `<a class="wow-card" href="#/discover/${a.id}"><div class="wow-orbit">${I(a.words.includes('tech')?'code-2':a.words.includes('space')?'orbit':'lightbulb')}</div><span class="eyebrow">${a.tag}</span><h3>${a.title}</h3><p>${a.levels[state.age]}</p><span class="text-link">Tell me why ${I('arrow-right')}</span></a>`}
function pageNumber(count){return Math.min(Math.max(0,Number(new URLSearchParams(location.hash.split('?')[1]).get('page'))||0),Math.max(0,Math.ceil(count/24)-1))}
function pagination(count,to){const page=pageNumber(count),pages=Math.ceil(count/24);return pages>1?`<nav class="collection-pagination" aria-label="More discoveries">${page?link(to+'?page='+(page-1),'Previous','chip','arrow-left'):''}<span>Page ${page+1} of ${pages}</span>${page+1<pages?link(to+'?page='+(page+1),'More discoveries','chip'):''}</nav>`:''}
function collectionPage(kind){const isStory=kind==='story',items=articles.filter(a=>a.kind===kind);return intro(isStory?'Zuno Story Studio':'Little Wows · A small fact, a bigger question',isStory?'Good stories. Bright ideas.':'Wait… really?',isStory?'Original stories about inventing, noticing, kindness and thinking things through.':'Short discoveries to enjoy, question and connect. Pick one and follow your curiosity.')+`<section class="collection-banner ${isStory?'':'wows-banner'}"><div><div class="eyebrow">Made for ${bands[state.age].name} · Ages ${state.age}</div><h2>${isStory?'Every adventure starts with a question.':'A little wonder goes a long way.'}</h2><p>${isStory?'Fictional characters. Real thinking skills. Every story has its own reading edition and a question to take away.':'A surprising idea, a clear explanation and something to think about. There is a natural stopping point: no endless feed.'}</p><button class="chip" data-action="age">${I('settings-2')}Change reading level</button></div>${isStory?'<img src="/assets/stories-cover.webp" alt="Illustration of two Kenyan children exploring a homemade robot and a book">':`<div class="wow-banner-art" aria-hidden="true">${I('lightbulb')}${I('orbit')}${I('leaf')}</div>`}</section><div class="${isStory?'article-grid':'wow-grid'}">${items.slice(pageNumber(items.length)*24,(pageNumber(items.length)+1)*24).map(isStory?articleCard:wowCard).join('')}</div>${pagination(items.length,'discover/'+(isStory?'stories':'wows'))}`}

let searchIndex;
function results(q,cat){let found=articles;if(q.trim()){if(searchIndex){const ids=searchIndex.search(q,{prefix:true,fuzzy:.2,combineWith:'AND'}).map(r=>r.id);found=ids.map(id=>articles.find(a=>a.id===id)).filter(Boolean)}else found=articles.filter(a=>(a.title+' '+a.words+' '+a.question).toLowerCase().includes(q.toLowerCase()));}return found.filter(a=>cat==='all'||a.category===cat)}
function library(){const found=results(search,category);return intro('The Zuno encyclopedia','A rabbit hole of good questions.','Find a story, follow an idea, discover something new.')+`<form class="searchbar" id="search-form"><label for="library-search" class="sr-only">Search discoveries</label>${I('search')}<input id="library-search" name="q" type="search" autocomplete="off" placeholder="Try planets, rhinos, coding…" value="${esc(search)}"><button class="button">Search</button></form><div class="filter-row" aria-label="Filter by topic"><button class="chip ${category==='all'?'active':''}" data-category="all" aria-pressed="${category==='all'}">All topics</button>${worlds.map(w=>`<button class="chip ${category===w.id?'active':''}" data-category="${w.id}" aria-pressed="${category===w.id}">${w.name}</button>`).join('')}</div><div class="section-head"><h2>${search?'Your discoveries':category==='all'?'Pick your next discovery':worldOf(category).name}</h2><span class="reading-level" role="status">${found.length} ${found.length===1?'discovery':'discoveries'} · Ages ${state.age}</span></div><div class="article-grid">${found.length?found.slice(pageNumber(found.length)*24,(pageNumber(found.length)+1)*24).map(articleCard).join(''):`<div class="empty"><h3>No discoveries here yet.</h3><p>Try “space”, “water” or “Kenya”. There are more worlds on the way.</p><button class="button light" data-action="clear-search">Show all discoveries</button></div>`}</div>${pagination(found.length,'discover/library')}`}
function articlePage(id){const a=articles.find(a=>a.id===id);if(!a)return missing();const story=a.kind==='story',wow=a.kind==='wow';return `<a href="#/discover/${story?'stories':wow?'wows':'library'}" class="back">${I('arrow-left')}Back to ${story?'Story Studio':wow?'Little Wows':'discoveries'}</a><div class="reading-layout"><article class="reader ${story?'story-reader':''}"><div class="eyebrow">${worldOf(a.category).name} · ${wow?'A short discovery':a.minutes+' min of '+(story?'story':'wonder')}</div><h1>${a.title}</h1><div class="reading-level">${bands[state.age].name} · Ages ${state.age}${story?' · Original fiction':''}</div><div class="reader-tools"><button class="chip icon-button" data-action="speak" data-id="${id}" aria-label="Read aloud" title="Read aloud">${I('volume-2')}</button><button class="chip ${state.saved.includes(id)?'active':''}" aria-pressed="${state.saved.includes(id)}" aria-label="${state.saved.includes(id)?'Remove from saved discoveries':'Save for later'}" title="${state.saved.includes(id)?'Saved':'Save for later'}" data-action="save" data-id="${id}">${I('bookmark')}</button><button class="chip" data-action="age">${I('settings-2')}Reading level</button></div>${!story?`<button class="chip reader-ai-explain" data-ai-topic="${id}">${I('sparkles')}Explain with Zuno</button>`:''}${editorialImage(a,true)}<p class="lead">${a.levels[state.age]}</p>${story||wow?'':`<div class="fact-inline">${I('lightbulb')} &nbsp; ${a.fact}</div>`}${sectionsFor(a,state.age).map(([title,text])=>`<section class="reading-section"><h2>${title}</h2><p>${text}</p></section>`).join('')}${a.reflect?`<aside class="story-reflection"><span class="eyebrow">Take a thought with you</span><h2>Your turn to wonder</h2><p>${a.reflect[state.age]}</p><small>Think, draw or talk it through. You don’t need to type personal details.</small></aside>`:''}<div class="reader-tools">${id==='solar-system'?link('explore/space','See the planets','button light','orbit'):id==='algorithms'?link('play/code','Code a route','button light','code-2'):id==='electricity'?link('explore/lab-circuit','Try the virtual circuit','button light','lightbulb'):link('ask?topic='+id,'Ask a related question','button light','message-circle')}</div><button class="button ${state.read.includes(id)?'light':''}" data-action="read" data-id="${id}">${I('check-circle-2')}${state.read.includes(id)?'Discovery completed':'I’ve finished reading · +10 XP'}</button><div class="source">${a.url?`Reading reference: <a href="${a.url}" target="_blank" rel="noopener noreferrer" data-external="true">${a.source} ↗</a>`:a.source+'.'}<br>${story?'Original ZUNO fiction with fictional characters. Illustrations are thematic, not documentary photographs.':'Written for ZUNO. Reference links open outside the app with a grown-up.'}<button class="text-link report-button" data-action="report">Something seems wrong?</button></div></article><aside class="related mini-panel"><h3>Keep wondering</h3>${a.related.map(id=>articles.find(x=>x.id===id)).filter(Boolean).map(x=>`<a href="#/discover/${x.id}">${x.title} ${I('arrow-right')}</a>`).join('')}<p class="reading-level">One question opens another door.</p></aside></div>`}

function exploreHub(){return intro('Step inside a new adventure','Explore Worlds','Look closer. Tap around. See how things connect.')+`<div class="game-grid">${[['space','Our solar system','Fly around eight planets. Choose a world and discover its story.','Interactive 3D','orbit'],['kenya','Hello, Kenya!','Tap 47 counties, compare places and follow a changemaker’s timeline.','Map & timeline','globe-2'],['wildlife','Into the wild','Meet Kenya’s wild neighbours and discover their remarkable adaptations.','Wildlife field guide','leaf']].map(([id,t,d,label,icon])=>`<a class="game-card ${worldOf(id==='wildlife'?'animals':id).color}" href="#/explore/${id}">${editorialImage({id:id==='kenya'?'kenya-photo':id,category:id==='wildlife'?'animals':id})}<div class="article-body"><h3>${t}</h3><p>${d}</p><span class="button light">Explore this world ${I(icon)}</span></div></a>`).join('')}</div><div class="callout">${I('lightbulb')}<p>You don’t have to know all the answers. Exploring is how we find the next question.</p></div>${section('Small labs. Big questions.')}${labCards()}`}
function spacePage(){return `<a class="back" href="#/explore">${I('arrow-left')}All worlds</a>`+intro('Your first space expedition','One star. Eight incredible worlds.','Tap a planet or use the buttons below. On 3D-capable devices, drag gently to change your view.')+`<div class="world-stage"><div id="solar-canvas" aria-label="Interactive solar system model"></div><div class="world-caption"><p>Illustrative model. Sizes, distances and orbital speeds are not to scale.</p><button id="orbit-pause" class="button ghost" data-action="orbit-pause" data-paused="${state.motion||matchMedia('(prefers-reduced-motion: reduce)').matches}">${I(state.motion||matchMedia('(prefers-reduced-motion: reduce)').matches?'play':'pause')}${state.motion||matchMedia('(prefers-reduced-motion: reduce)').matches?'Play orbits':'Pause orbits'}</button><button class="button ghost" data-action="orbit-reset">${I('rotate-ccw')}Reset view</button></div></div><div class="planet-buttons" aria-label="Choose a planet">${['Mercury','Venus','Earth','Mars','Jupiter','Saturn','Uranus','Neptune'].map((n,i)=>`<button class="chip ${i===2?'active':''}" data-planet="${i}" aria-pressed="${i===2}"><span class="planet-dot" style="--pcolor:${['#b5a492','#dca855','#548cff','#c46543','#bc946d','#dcc396','#7cbfc8','#526fe8'][i]}"></span>${n}</button>`).join('')}</div><section id="planet-info" class="planet-info" aria-live="polite"></section><div class="callout">${I('rocket')}<p>Ready to put your space discoveries to the test?</p>${link('play/space','Try the space quiz','button','arrow-right')}</div>`}
const regions=[{title:'The Great Rift Valley',label:'Landscapes shaped by time',text:'From dramatic escarpments to lakes and volcanic landforms, the rift tells a story millions of years in the making. Find out what is happening beneath your feet.',article:'rift-valley',name:'Rift Valley'},{title:'Kenya’s wild neighbours',label:'Look closely. Keep your distance.',text:'Elephants and black rhinos have remarkable adaptations. Explore how their bodies help them find food, communicate and survive.',article:'rhinos',name:'Wildlife'},{title:'Our coastal blue',label:'A world beneath the waves',text:'Kenya’s coast is connected to a wonderful marine world. Meet the tiny animals that help build coral reefs and discover why these habitats matter.',article:'coral',name:'The coast'},{title:'Ideas that grow',label:'People who make a difference',text:'Wangari Maathai showed how caring for trees could connect communities, livelihoods and peace. Discover the story of a Kenyan changemaker.',article:'wangari',name:'Changemakers'}];
let regionIndex=0;
function regionPage(wild=false){const r=wild?{title:'The elephant’s secret toolkit',label:'A remarkable trunk',text:articles.find(a=>a.id==='elephants').levels[state.age],article:'elephants',name:'Elephants'}:regions[regionIndex];return `<a class="back" href="#/explore">${I('arrow-left')}All worlds</a>`+intro(wild?'Wildlife field guide':'Kenya field guide',wild?'Extraordinary neighbours.':'Wonder begins right here.',wild?'Meet the animals. Discover their adaptations.':'Choose a stop and follow the story. This is a field guide, not a map.')+(!wild?`<div class="region-tabs" aria-label="Choose a field guide stop">${regions.map((x,i)=>`<button class="chip ${i===regionIndex?'active':''}" data-region="${i}" aria-pressed="${i===regionIndex}">${x.name}</button>`).join('')}</div>`:'')+`<div class="region-card">${editorialImage(articles.find(a=>a.id===r.article),true)}<div class="region-details"><h2>${r.title}</h2><p>${r.text}</p>${link('discover/'+r.article,'Follow this story','button','book-open')}</div></div>${section(wild?'Meet the neighbours':'More to discover','discover?category='+ (wild?'animals':'kenya'))}<div class="article-grid">${articles.filter(a=>wild?a.category==='animals':['rift-valley','wangari','coral'].includes(a.id)).map(articleCard).join('')}</div>`}
function chatHistoryHTML(dialog=false){const searchId=dialog?'chat-history-search-dialog':'chat-history-search';return `<div class="chat-history-top"><h2>Your chats</h2><button class="chip icon-button" data-action="new-chat" aria-label="Start a new chat" title="New chat">${I('square-pen')}</button></div><p class="chat-storage-note">${chatStore.remember?'Saved on this device · 7 days':'Kept in this tab · no account sync'}</p><label class="sr-only" for="${searchId}">Find a chat</label><input id="${searchId}" class="chat-history-search" type="search" placeholder="Find a chat…"><div class="chat-thread-list">${chatStore.data.threads.length?chatStore.data.threads.map(t=>`<div class="chat-thread-row" data-thread-title="${esc(t.turns[0]?.question.toLowerCase()||'')}"><button class="chat-thread ${chatStore.data.active===t.id?'selected':''}" data-chat-id="${esc(t.id)}" ${chatStore.data.active===t.id?'aria-current="true"':''}><strong>${esc(t.turns[0]?.question.slice(0,56)||'A new discovery')}</strong><small>${t.turns.length} ${t.turns.length===1?'question':'questions'} · ${new Date(t.updated).toLocaleDateString('en-GB',{day:'numeric',month:'short'})}</small></button><button class="chat-remove" data-remove-chat="${esc(t.id)}" aria-label="Remove chat: ${esc(t.turns[0]?.question.slice(0,56)||'A new discovery')}">${I('x')}</button></div>`).join(''):'<p class="chat-no-history">Your questions will collect here. Start with something that makes you wonder.</p>'}</div>${removedChat?'<button class="text-link" data-action="undo-chat">Undo removed chat</button>':''}<a class="text-link chat-history-settings" href="#/parents" data-action="close-dialog">${I('shield-check')}History settings</a><nav class="history-policies" aria-label="Policies">${policyLinks()}</nav>`}
function chatTurnHTML(turn,index){
 const a=articles.find(x=>x.id===turn.topic),guard=questionGuard(turn.question),live=turn.ai,age=live?.ageBand||state.age,greeting=guard.kind==='question'?conversationReply(turn.question,age):null;
 const fallback=guard.message||(turn.aiError||(aiReady(state.age)?'Try a different learning question, or explore a library discovery.':null))||(turn.kind==='privacy'?'Private details were left out.':turn.kind==='support'?'If something worries you or someone is unsafe, tell a trusted grown-up.':'I could not complete this answer. Try rephrasing your question or explore a related discovery.');
 const answer=live?.answer?.replace(/\n+Sources?:\s*S\d+(?:[,\s]+S\d+)*\s*$/i,'')||greeting?.answer||(a?(turn.detail==='more'?sectionsFor(a,age).map(x=>x[1]).join('\n\n'):turn.detail==='simple'?a.levels['6-8']:a.levels[age]):fallback),sources=live?.sources||[];
 const activity=turn.pending?`<div class="chat-ai-loading" role="status">${I('search')}Finding a checked explanation<span class="loading-dots" aria-hidden="true"></span></div>`:greeting?``:`<details class="chat-activity"><summary>${I(live?'shield-check':a?'book-open':'lightbulb')}${live?'AI answer checked':a?'Library answer ready':'A starting point'}${I('chevron-down')}</summary><ol>${live?live.events.map(e=>`<li>${esc(e.label)}</li>`).join(''):`<li>Checked common private or sensitive details</li><li>${a?'Matched a ZUNO discovery':'No suitable library match'}</li><li>Selected the reading edition</li>`}</ol><p>${live?'AI checks can miss errors. Important information still needs a trusted adult.':'Local library lookup. No model or internet search was used for this answer.'}</p></details>`;
 const references=live&&sources.length?`<div class="chat-sources"><span>Sources used</span>${sources.map(source=>{const internal=source.url.startsWith('https://zuno-kids.creativehub254.chatgpt.site/#/'),url=internal?'#'+source.url.split('/#')[1]:source.url;return `<a class="chat-source-card" href="${esc(url)}" ${internal?'':'data-external="true" target="_blank" rel="noopener noreferrer"'}>${I(internal?'book-open':'globe-2')}<span><small>${internal?'ZUNO discovery':'Reference source'}</small><strong>${esc(source.title)}</strong></span>${I('arrow-right')}</a>`}).join('')}</div>`:a?`<div class="chat-sources"><span>Sources & discoveries</span><a class="chat-source-card" href="#/discover/${a.id}">${I('book-open')}<span><small>ZUNO discovery</small><strong>${esc(a.title)}</strong></span>${I('arrow-right')}</a>${a.url?`<a class="chat-source-card" href="${esc(a.url)}" data-external="true" target="_blank" rel="noopener noreferrer">${I('globe-2')}<span><small>Reference source</small><strong>${esc(a.source)}</strong></span>${I('arrow-right')}</a>`:''}</div>`:'';
 return `<section class="chat-turn" id="chat-turn-${index}"><div class="chat-user"><span class="sr-only">Your question:</span>${esc(turn.question)}</div><div class="chat-zuno"><img class="chat-avatar" src="/assets/zuno-icon.webp" alt=""><div class="chat-answer-content"><div class="chat-speaker">Zuno AI <span>${bands[age].name} · Ages ${age}</span></div>${activity}${!turn.pending?`<div class="chat-answer-text"><p>${esc(answer).replace(/\n\n/g,'</p><p>')}</p></div>${turn.aiError&&a?`<div class="chat-ai-error" role="status">${esc(turn.aiError)}</div>`:''}${references}<div class="chat-followups">${greeting?greeting.prompts.map(p=>`<button class="chip" data-question="${esc(p)}">${esc(p)}</button>`).join(''):live||a?'<button class="chip" data-question="Tell me more">Tell me more</button><button class="chip" data-question="Explain it simply">Explain it simply</button>':link('discover/library','Browse discoveries','text-link')}</div><button class="text-link report-button" data-action="report">Something seems wrong?</button>`:''}</div></div></section>`
}

function askPage(){const turns=chatStore.current()?.turns||[];return `<section class="zuno-chat-layout"><aside class="chat-history-desktop" aria-label="Chat history">${chatHistoryHTML()}</aside><div class="chat-room"><header class="chat-room-header"><div class="chat-room-brand"><img src="/assets/zuno-icon.webp" alt=""><div><h1>Zuno AI</h1><p>${I('sparkles')}Your learning companion · Ages ${state.age}</p></div></div><div class="chat-room-tools"><button class="chip icon-button chat-mobile-history" data-action="chat-history" aria-label="Chat history" title="History">${I('clock-3')}</button><button class="chip icon-button" data-action="new-chat" aria-label="New chat" title="New chat">${I('square-pen')}</button></div></header><div class="chat-transcript" aria-label="Conversation">${turns.length?turns.map(chatTurnHTML).join(''):`<div class="chat-welcome"><span class="eyebrow">A BIG QUESTION STARTS SOMETHING GOOD</span><img src="/assets/zuno-icon.webp" alt="Zuno, ready to explore"><h2><span class="sr-only">What made you wonder today?</span><span class="rotating-heading" aria-hidden="true" data-rotating="chat">What made you wonder today?</span></h2><p>Follow a question. Find a new idea.</p><div class="chat-starters">${[['orbit','Why is Mars red?'],['leaf','How do elephants use their trunks?'],['code-2','What is an algorithm?'],['globe-2','Where does rain come from?']].map(([icon,q])=>`<button data-question="${q}">${I(icon)}<span>${q}</span>${I('arrow-right')}</button>`).join('')}</div></div>`}</div><div class="chat-composer-wrap"><form class="ask-form chat-composer" id="ask-form"><label class="sr-only" for="question">Your question for Zuno</label><textarea id="question" name="question" rows="1" placeholder="What are you curious about?" maxlength="600" autocomplete="off" required>${esc(chatDraft)}</textarea><button class="button zuno-send" type="submit" ${aiBusy?'disabled':''} aria-label="Send your question" title="Send">${SEND_PLANE}</button></form></div></div></section>`}
async function answerQuestion(q,taskOverride){if(aiBusy)return;q=String(q||'').trim().slice(0,600);if(!q)return;if(q===lastSubmission.text&&Date.now()-lastSubmission.at<900)return;lastSubmission={text:q,at:Date.now()};const guard=questionGuard(q);let a=null,detail=null;const current=chatStore.current(),last=current?.turns.slice().reverse().find(t=>t.topic);if(guard.kind==='question'){if(last&&/^(tell me more|explain it simply|make it simpler)[.!?]?$/i.test(q)){a=articles.find(x=>x.id===last.topic);detail=/more/i.test(q)?'more':'simple'}else{const clean=q.replace(/\b(what|is|a|an|the|how|do|does|why|are|in|our|can|i|you|tell|me|about|from|where|come|of|to|and)\b/gi,' ').trim();a=articles.find(x=>x.question.toLowerCase()===q.toLowerCase())||(clean?results(clean,'all')[0]:null);if(!a&&last&&/\b(it|its|that|this)\b/i.test(q)&&/^(why|how|what|can)\b/i.test(q)){const prior=articles.find(x=>x.id===last.topic),combined=results(clean.replace(/\b(it|its|that|this)\b/gi,' ')+' '+prior?.title,'all');a=combined.find(x=>x.id===last.topic)||null;}}}const online=guard.kind==='question'&&!conversationReply(q,state.age),replyId=crypto.randomUUID(),prior=current?.turns.slice().reverse().find(t=>! /^(tell me more|explain it simply|make it simpler)[.!?]?$/i.test(t.question)),thread=chatStore.add({replyId,question:guard.question,topic:a?.id||null,kind:guard.kind==='question'?(a?'question':'missing'):guard.kind,detail,pending:online});chatDraft='';aiBusy=online;render(false);$('#question')?.focus({preventScroll:true});const transcript=$('.chat-transcript'),turn=$('.chat-turn:last-child');if(transcript&&turn)transcript.scrollTo({top:turn.offsetTop,behavior:reduced()?'instant':'smooth'});if(!online)return;aiAbort=new AbortController();const controller=aiAbort,answerAge=state.age;const question=prior&&(/^(tell me more|explain it simply|make it simpler)[.!?]?$/i.test(q)||/\b(it|its|that|this|they|their)\b/i.test(q))?('Earlier question: '+prior.question+'. Follow-up: '+q).slice(0,600):q;try{const result=await askAI({question,ageBand:answerAge,task:taskOverride||(detail==='simple'||/^(explain it simply|make it simpler)[.!?]?$/i.test(q)?'explain':'chat'),signal:controller.signal});if(!controller.signal.aborted){if(result.mode==='ai')chatStore.updateTurn(thread.id,replyId,{ai:result,pending:false});else chatStore.updateTurn(thread.id,replyId,{topic:null,pending:false,aiError:result.answer||aiError(result.code)})}}catch(error){chatStore.updateTurn(thread.id,replyId,{pending:false,aiError:controller.signal.aborted?'Answer stopped.':aiError(error.code)})}finally{if(aiAbort===controller){aiBusy=false;aiAbort=null;render(false)}}}
function playHub(){const done=state.read.includes('solar-system'),explored=state.days[dateKey()]?.includes?.('explore:space'),played=state.played.includes('space');return intro('A little practice. A lot of possibility.','Play with what you know.','Tiny challenges for growing minds. Mistakes are welcome here.')+`<div class="path-banner"><div><div class="eyebrow">Your space explorer path</div><h2>Read it. Explore it. Try it.</h2><p>Three ways to make one big idea stick. Choose any step.</p></div><div class="path-steps" aria-label="Space explorer path"><a href="#/discover/solar-system" aria-label="Read the solar system story"><span class="${done?'done':''}">${I('book-open')}</span></a><a href="#/explore/space" aria-label="Explore the solar system"><span class="${explored?'done':''}">${I('orbit')}</span></a><a href="#/play/space" aria-label="Try the space quiz"><span class="${played?'done':''}">${I('gamepad-2')}</span></a></div></div><div class="game-grid">${Object.entries(quizzes).map(([id,q])=>`<a class="game-card ${worldOf(q.category).color}" href="#/play/${id}">${art(q.category,'3 QUESTIONS · NO TIMER')}<div class="article-body"><h3>${q.title}</h3><p>${q.description}</p><span class="button light">${state.played.includes(id)?'Play again':'Start a little adventure'} ${I('arrow-right')}</span></div></a>`).join('')}<a class="game-card blue" href="#/play/code">${art('tech','BUILD · TEST · DEBUG')}<div class="article-body"><h3>Code a route</h3><p>Give your rover a sequence of steps. Can you reach the star?</p><span class="button light">Let’s build ${I('code-2')}</span></div></a></div>`}
function quizPage(id){const q=quizFor(id,state.age,quizzes);if(!q)return missing();if(!quizState||quizState.id!==id)quizState={id,index:0,selected:null,checked:false,score:0,done:false,newXP:false,questions:q.questions.map(item=>shuffleQuestion(item))};const s=quizState;if(s.done)return `<div class="quiz-wrap"><a class="back" href="#/play">${I('arrow-left')}Back to play</a><div class="quiz-card celebration">${I('trophy')}<div class="eyebrow">Look what you’ve discovered</div><h1>Your curiosity is growing!</h1><p>${s.score} of ${q.questions.length} correct on your first try. Every explanation is another discovery.</p><div class="fact-inline">${s.newXP?'+30 curiosity points!':'You’ve already earned this adventure’s points.'} Keep practising whenever you like.</div>${link('universe','See my universe','button')} <button class="chip" data-action="retry-quiz">Try again</button></div></div>`;const item=s.questions[s.index];return `<div class="quiz-wrap"><a class="back" href="#/play">${I('arrow-left')}Leave this adventure</a><div class="quiz-top"><div class="progress" role="progressbar" aria-label="Quiz progress" aria-valuenow="${s.index}" aria-valuemin="0" aria-valuemax="${q.questions.length}"><span style="width:${s.index/q.questions.length*100}%"></span></div><span>${s.index+1} of ${q.questions.length}</span></div><div class="quiz-card"><img class="world-icon" src="/assets/${worldOf(q.category).icon}.webp" alt=""><div class="eyebrow">${q.title}</div><h1>${item.q}</h1><div class="quiz-options" role="group" aria-label="Choose your answer">${item.options.map((o,i)=>`<button class="quiz-option ${s.selected===i?'selected':''} ${s.checked&&i===item.correct?'correct':''} ${s.checked&&s.selected===i&&i!==item.correct?'incorrect':''}" data-option="${i}" aria-pressed="${s.selected===i}" ${s.checked?'disabled':''}><span>${s.checked&&i===item.correct?I('check'):String.fromCharCode(65+i)}</span>${o}</button>`).join('')}</div>${s.checked?`<div class="feedback" tabindex="-1" role="status"><strong>${s.selected===item.correct?'You’ve got it!':'Good try. Here’s the discovery.'}</strong>${item.why}</div><button class="button" data-action="next-question">${s.index===q.questions.length-1?'Finish my adventure':'Next discovery'} ${I('arrow-right')}</button>`:`<button class="button" data-action="check-answer" ${s.selected===null?'disabled':''}>Check my answer ${I('check')}</button>`}</div></div>`}
function codePage(){const c=codeConfig(state.age),walls=new Set(c.walls),goal=c.size-1;return `<a class="back" href="#/play">${I('arrow-left')}All adventures</a>`+intro('Future Lab · Ages '+state.age,'Code a route. Catch a star.',state.age==='6-8'?'Choose one step at a time. Start at the bottom left.':state.age==='12-14'?'Build, test and debug. Can you find a route in '+c.target+' moves?':'Build a sequence. Predict the route, then test your idea.')+`<div class="code-layout"><section class="mini-panel"><h2>Your rover’s world</h2><p>Reach the top-right star. Avoid the blocks and edges.</p><div class="code-board" style="grid-template-columns:repeat(${c.size},1fr)" role="img" aria-label="${c.size} by ${c.size} grid. Rover at row ${Math.floor(codeState.pos/c.size)+1}, column ${codeState.pos%c.size+1}. Star at row one, column ${c.size}. Blocked squares: ${c.walls.map(i=>'row '+(Math.floor(i/c.size)+1)+' column '+(i%c.size+1)).join('; ')}.">${Array.from({length:c.size*c.size},(_,i)=>`<div class="cell ${walls.has(i)?'wall':''} ${i===codeState.pos?'rover':''} ${i===goal?'goal':''}">${i===codeState.pos?I('rocket'):i===goal?I('star'):''}</div>`).join('')}</div><p class="not-scale">One arrow moves one square. There is a clear route around the bottom and right edges.</p></section><section class="mini-panel"><h2>You’re the programmer.</h2><p>Add up to ${c.max} steps. Tap a step to remove it.</p><div class="code-controls">${[['up','↑'],['down','↓'],['left','←'],['right','→']].map(([d,s])=>`<button class="button light" data-step="${d}" aria-label="Add move ${d}" ${codeState.running?'disabled':''}>${s} ${d}</button>`).join('')}</div><div class="sequence" aria-label="Your program">${codeState.steps.length?codeState.steps.map((d,i)=>`<button data-remove-step="${i}" aria-label="Remove step ${i+1}: ${d}" ${codeState.running?'disabled':''}>${i+1}. ${{up:'↑',down:'↓',left:'←',right:'→'}[d]}</button>`).join(''):'<p>Your instructions will appear here.</p>'}</div><div class="code-controls"><button class="button" data-action="run-code" ${!codeState.steps.length||codeState.running?'disabled':''}>${I('play')}Run my code</button><button class="button white" data-action="reset-code" ${codeState.running?'disabled':''}>${I('rotate-ccw')}Clear</button></div><div id="code-feedback" class="feedback" role="status">${codeState.message||'Predict, run, notice, improve. There’s no timer.'}</div></section></div>`}
async function runCode(){const c=codeConfig(state.age),walls=new Set(c.walls),runAge=state.age;codeState.pos=c.size*(c.size-1);codeState.running=true;codeState.message='Running your instructions…';render(false);const routeToken=location.hash;for(let i=0;i<codeState.steps.length;i++){await new Promise(r=>setTimeout(r,reduced()?30:260));if(location.hash!==routeToken||state.age!==runAge){codeState.running=false;return}const d=codeState.steps[i],p=codeState.pos,n=p+({up:-c.size,down:c.size,left:-1,right:1}[d]);if(n<0||n>=c.size*c.size||(d==='left'&&p%c.size===0)||(d==='right'&&p%c.size===c.size-1)||walls.has(n)){codeState.message=`Step ${i+1} needs debugging: ${walls.has(n)?'there is a block in the way':'that move goes off the grid'}. Change your steps and try again.`;break}codeState.pos=n;render(false)}codeState.running=false;if(codeState.pos===c.size-1){const fresh=completeGame('code');codeState.message=fresh?'You did it! Your algorithm reached the star. +25 curiosity points.':'Your rover found the star again. Great debugging!'}else if(codeState.message==='Running your instructions…')codeState.message='The program finished before the star. Add or change some steps, then try again.';render(false)}

function universePage(){const badgeData=[['compass','First discovery','Finish one story.',state.read.length>0],['rocket','Space explorer','Complete the space quiz.',state.played.includes('space')],['code-2','Future builder','Guide the rover to the star.',state.played.includes('code')]];return intro('Your very own corner of the cosmos','My Universe','A collection of little things that made your world bigger.')+`<section class="universe-hero"><img src="/assets/zuno-icon.webp" alt="Zuno smiling"><div><div class="eyebrow">${bands[state.age].name} · Ages ${state.age}</div><h2>Powered by your curiosity.</h2><p>${xp()?'Look at all the places your questions have taken you.':'Your adventure starts with one little question.'}</p><span class="reading-level">Progress stays in this browser. No account or real name needed for this preview.</span></div></section><div class="stats-row">${[['star',xp(),'curiosity points'],['book-open',state.read.length,'stories discovered'],['gamepad-2',state.played.length,'adventures completed']].map(([i,n,t])=>`<div class="stat">${I(i)}<strong>${n}</strong><span>${t}</span></div>`).join('')}</div>${section('Little milestones')}<div class="badge-grid">${badgeData.map(([i,t,d,earned])=>`<div class="achievement ${earned?'':'locked'}">${I(i)}<h3>${t}</h3><p>${earned?'You earned this!':d}</p></div>`).join('')}</div>${section('Saved for another adventure','discover/library','Find more')}<div class="article-grid">${state.saved.length?state.saved.map(id=>articles.find(a=>a.id===id)).map(articleCard).join(''):`<div class="empty"><h3>A home for your favourite discoveries.</h3><p>Tap “Save for later” on a story to keep it here.</p>${link('discover/library','Find a discovery','button light')}</div>`}</div>${state.read.length?section('Places your mind has been')+`<div class="article-grid">${state.read.slice(-4).reverse().map(id=>articles.find(a=>a.id===id)).map(articleCard).join('')}</div>`:''}`}
function parentPage(){return `<div class="mini-panel ai-parent-panel"><h2>Connected Zuno AI</h2><p>Zuno AI, powered by ClerkOps, provides age-based explanations, learning hints and safe creative conversation. No provider keys are stored in this app.</p><button class="button" data-action="ai-preview">Connection details ${I('message-circle')}</button></div>`+`<section class="settings-page">${intro('A little clarity for the grown-ups','Built around curious minds.','This is a development preview, not a launched child account service.')}<div class="mini-panel"><h2>What works in this preview</h2><p>An expanding collection of explainers, eighteen original stories and Little Wows, with full reading editions for three age bands. There are four programmed labs, a solar explorer with a lightweight fallback, a 47-county Kenya learning map and timeline, age-based quizzes, a coding puzzle, bookmarks and progress. Zuno AI connects for learning explanations, hints and safe ideas. Library mode stays available.</p><div class="setting"><div><strong>Colour mode</strong><small>Choose light reading or a cosmic dark surface.</small></div><button class="chip" data-action="theme">${state.theme==='light'?'Use dark colours':'Use light colours'}</button></div><div class="setting"><div><strong>Reading level</strong><small>${bands[state.age].name} · Ages ${state.age}</small></div><button class="chip" data-action="age">Change</button></div><div class="setting"><div><strong>Larger reading text</strong><small>Give stories a little more breathing room.</small></div><button class="toggle" role="switch" aria-checked="${state.large}" aria-label="Larger reading text" data-toggle="large"></button></div><div class="setting"><div><strong>Reduce motion</strong><small>Pause default orbit motion and shorten transitions.</small></div><button class="toggle" role="switch" aria-checked="${state.motion}" aria-label="Reduce motion" data-toggle="motion"></button></div></div><div class="settings-grid"><div class="mini-panel"><h2>Privacy, in plain words</h2><p>No advertising, public profiles or messaging. No microphone, camera or location access. Zuno AI history stays in this browser tab by default. Optional device history expires after seven days. It is separate from learning progress and is not synced to an account. Reading level, bookmarks and activity stay in this browser.</p><div class="setting"><div><strong>Remember chats on this device</strong><small>Off by default for shared devices. On: keep up to 12 chats for seven days. Avoid personal details.</small></div><button class="toggle" role="switch" aria-checked="${chatStore.remember}" aria-label="Remember chats on this device" data-action="remember-chat"></button></div><p>Device read-aloud voices depend on your browser and operating system.</p><p>${storageOK?'Browser progress saving is available.':'This browser is not allowing progress to be saved.'}</p><button class="text-link danger" data-action="confirm-reset">Clear this browser’s progress ${I('rotate-ccw')}</button></div><div class="mini-panel"><h2>Before children’s accounts launch</h2><p>Verified parent sign-in and consent, server-side safety checks, age-appropriate AI evaluations, provider eligibility, retention/deletion controls and educator review are required. The reading-level picker is a preview control, not age verification.</p><p>Verified child accounts are not enabled. Zuno AI connects automatically for learning questions. This release is educational only: no shop, subscriptions or checkout.</p></div></div><div class="mini-panel"><h2>Rooted in Kenya, open to everyone</h2><p>ZUNO is an independent discovery app. Global science, technology, reading and thinking activities sit alongside Kenyan examples. A child does not need Kenyan school knowledge to understand the main discovery paths. Curriculum mapping and educator review are planned; these lessons are not KICD-approved.</p><div class="school-topics"><a class="chip" href="https://kicd.ac.ke/cbc-materials/curriculum-designs/" target="_blank" rel="noopener noreferrer" data-external="true">KICD curriculum designs ↗</a><a class="chip" href="https://www.kec.ac.ke/" target="_blank" rel="noopener noreferrer" data-external="true">Kenya Education Cloud ↗</a></div><p>Official programmes are linked as references. Their materials have not been copied into ZUNO.</p></div><div class="mini-panel"><h2>A healthy kind of progress</h2><p>Short learning paths, quick feedback and repeat practice. No lost lives, punitive streaks, public rankings or pressure to keep playing. Curiosity points are just for encouragement. Breaks are always welcome.</p></div><a class="text-link" href="/build-plan.md" target="_blank" rel="noopener noreferrer">Product architecture & staged plan</a><br><a class="text-link" href="/third-party.html">Open-source acknowledgements ${I('arrow-right')}</a></section>`}
function missing(){return `<div class="empty"><h1>This world is still waiting to be discovered.</h1><p>Let’s head back to a familiar place.</p>${link('discover','Back to Discover','button')}</div>`}
function render(scroll=true){motionObserver?.disconnect();if(worldCleanup){worldCleanup();worldCleanup=null}if('speechSynthesis'in window)speechSynthesis.cancel();document.body.classList.toggle('read-large',state.large);document.body.classList.toggle('motion-off',state.motion);document.body.classList.toggle('theme-dark',state.theme==='dark');document.querySelector('meta[name="theme-color"]')?.setAttribute('content',state.theme==='dark'?'#161d38':'#ffffff');const raw=location.pathname.replace(/\/$/,'')==='/app/admin'&&!location.hash?'admin':location.hash.slice(2)||'welcome',[path,query]=raw.split('?'),[area,id]=path.split('/'),params=new URLSearchParams(query);let content,active=area;document.body.classList.toggle('chat-screen',area==='ask');document.body.classList.toggle('focus-activity',area==='play'&&Boolean(id)&&(tracks.some(t=>t.id===id)?Boolean(path.split('/')[2])&&path.split('/')[2]!=='map':true));document.body.classList.toggle('detail-page',area==='explore'&&Boolean(id)||area==='discover'&&Boolean(id)&&!['library','stories','wows'].includes(id));document.body.classList.toggle('secondary-page',area==='parents'||['terms','privacy','safety','storage'].includes(area));
 document.body.classList.toggle('landing-page',area==='welcome');
 if(area==='admin'&&location.pathname.replace(/\/$/,'')==='/app/admin'){content=adminPage();active='parents'}else if(area==='welcome'){content=landing();active='welcome'}else if(area==='discover'){if(params.has('category')){category=worlds.some(w=>w.id===params.get('category'))?params.get('category'):'all';search='';content=library()}else if(id==='library')content=library();else if(id==='stories')content=collectionPage('story');else if(id==='wows')content=collectionPage('wow');else if(id)content=articlePage(id);else content=home()}
 else if(area==='ask'){if(params.has('topic')){const a=articles.find(a=>a.id===params.get('topic'));history.replaceState(null,'','#/ask');if(a)queueMicrotask(()=>answerQuestion(a.question))}content=askPage()}
 else if(area==='explore'){content=!id?exploreHub():id==='space'?spacePage():id==='kenya'?kenyaPage(state.age):id==='wildlife'?regionPage(true):labs.some(l=>l[0]===id)?labPage(id,state.age):missing()}
 else if(Object.hasOwn(policies,area)){content=policyPage(area);active='parents'}else if(area==='play'){const level=path.split('/')[2];content=!id?arcade(state.age):tracks.some(t=>t.id===id)?(level==='map'||!level?levelMap(id,state.age,params.has('chapter')?Number(params.get('chapter')):undefined):gamePage(id,Number(level),state.age,Object.keys(quizzes).flatMap(q=>quizFor(q,state.age,quizzes).questions))):id==='facts'?factsPage(state.age,Number(level)||1):id==='cube'?cubePage(state.age,Number(level)||1,{admin:isAdmin()}):id==='code'?codePage():quizPage(id)}else if(area==='universe')content=universePage();else if(area==='parents')content=parentPage();else{content=missing();active='discover'}
 const retainedSidebar=$('#app .sidebar'),retainedTopbar=$('#app .topbar');const retainedBrands=[...document.querySelectorAll('#app .brand,#app .mobile-brand')];$('#app').innerHTML=shell(content,active);if(retainedSidebar){const next=$('#app .sidebar');for(const img of retainedSidebar.querySelectorAll('.brand img')){const fresh=next.querySelector('.'+img.className);if(fresh)img.src=fresh.getAttribute('src')}for(const a of retainedSidebar.querySelectorAll('.nav a')){const selected=a.getAttribute('href')==='#/'+active;a.classList.toggle('active',selected);if(selected)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current')}next?.replaceWith(retainedSidebar)}if(retainedTopbar){const next=$('#app .topbar');const crumb=retainedTopbar.querySelector('.crumb');if(crumb)crumb.innerHTML=next.querySelector('.crumb').innerHTML;const oldTools=retainedTopbar.querySelector('.top-tools'),newTools=next.querySelector('.top-tools');if(oldTools.innerHTML!==newTools.innerHTML)oldTools.innerHTML=newTools.innerHTML;const brand=retainedTopbar.querySelector('.brand-lockup');if(brand)brand.src=next.querySelector('.brand-lockup').getAttribute('src');next.replaceWith(retainedTopbar)}for(const old of retainedBrands){const selector=old.classList.contains('mobile-brand')?'.mobile-brand':'.brand';const next=document.querySelector('#app '+selector);if(next&&old.querySelector('.brand-lockup')?.getAttribute('src')===next.querySelector('.brand-lockup')?.getAttribute('src'))next.replaceWith(old)}mountAdmin(render);mountGames({age:state.age,render,toast,reduced,onComplete:()=>activity('play:levels')});document.title=(area==='discover'&&id&&id!=='library'?(id==='stories'?'Story Studio':id==='wows'?'Little Wows':articles.find(a=>a.id===id)?.title||'Discover'):navItems.find(x=>x[0]===active)?.[2]||'Grown-up corner')+' · ZUNO KIDS';if(area==='welcome')document.title='ZUNO KIDS · Ask. Learn. Explore.';if(area==='admin')document.title='ZUNO Administration';
 if(area==='play'&&id==='cube')worldCleanup=mountCube({reduced:reduced(),toast,onComplete:()=>activity('play:cube')});if(area==='explore'&&id==='space')initSpace();if(area==='explore'&&id==='kenya')mountKenya(state.age).catch(()=>{const n=$('#kenya-map');if(n)n.innerHTML='<p>The map is unavailable offline until its first visit. You can still read the linked Kenya discoveries below.</p>'});if(area==='explore'&&labs.some(l=>l[0]===id))worldCleanup=mountLab(id,{age:state.age,reduced:reduced()});if(scroll){window.scrollTo({top:0,behavior:'instant'});if(!firstRender)$('#main').focus({preventScroll:true})}if(scroll)initMotion();if(!reduced()&&xp()>previousXP&&previousXP>0)$('.xp')?.animate([{transform:'scale(1)'},{transform:'scale(1.17)'},{transform:'scale(1)'}],{duration:420,easing:'cubic-bezier(.2,.8,.2,1)'});previousXP=xp();firstRender=false;
}
async function initSpace(){const node=$('#solar-canvas');node.innerHTML='<p class="loading-world">Getting your spacecraft ready…</p>';let cancelled=false;worldCleanup=()=>{cancelled=true};try{const probe=document.createElement('canvas');if(!probe.getContext('webgl2')&&!probe.getContext('webgl'))throw Error('WebGL unavailable');const mod=await import('./solar.js');if(cancelled||!node.isConnected)return;worldCleanup=mod.mountSolar(node,{reduced:state.motion||matchMedia('(prefers-reduced-motion: reduce)').matches,onSelect:updatePlanet});updatePlanet(selectedPlanet);window.dispatchEvent(new CustomEvent('zuno-planet',{detail:selectedPlanet}))}catch{if(!cancelled){const fallback=await import('./solar2d.js');if(cancelled||!node.isConnected)return;worldCleanup=fallback.mountSolar2D(node,{reduced:state.motion||matchMedia('(prefers-reduced-motion: reduce)').matches,onSelect:updatePlanet});updatePlanet(selectedPlanet);window.dispatchEvent(new CustomEvent('zuno-planet',{detail:selectedPlanet}))}}}
const planets=[['Mercury','A small rocky world closest to the Sun. Its surface is covered in craters.','88 Earth days'],['Venus','A rocky planet wrapped in a thick atmosphere. Venus is the hottest planet because its atmosphere traps heat.','225 Earth days'],['Earth','Our home world, with liquid oceans and a life-supporting atmosphere. One trip around the Sun takes about a year.','365.25 Earth days'],['Mars','A cold rocky planet with rusty red dust. Robotic explorers study its rocks and signs of ancient water.','687 Earth days'],['Jupiter','The largest planet in our solar system. This gas giant has powerful storms, including the Great Red Spot.','11.86 Earth years'],['Saturn','A gas giant known for spectacular rings made mostly of pieces of ice, with some rock and dust.','29.45 Earth years'],['Uranus','An ice giant that rotates at a dramatic tilt. Methane in its atmosphere contributes to its blue-green colour.','84 Earth years'],['Neptune','A distant ice giant with powerful winds. It is the farthest of the eight planets from the Sun.','164.8 Earth years']];
function updatePlanet(i){selectedPlanet=i;const p=planets[i];if(!p||!$('#planet-info'))return;$('#planet-info').innerHTML=`<div><div class="eyebrow">Planet ${i+1} from the Sun</div><h2>${p[0]}</h2><small>One orbit: about ${p[2]}</small></div><p>${p[1]}</p>`;document.querySelectorAll('[data-planet]').forEach(b=>{const active=Number(b.dataset.planet)===i;b.classList.toggle('active',active);b.setAttribute('aria-pressed',String(active))})}
function ageDialog(){const d=$('#settings');d.innerHTML=`<button class="close" data-action="close-dialog" aria-label="Close reading-level picker">${I('x')}</button><div class="eyebrow">An adventure that grows with you</div><h2>Find your reading level.</h2><p>Choose the words that feel right. You can change this any time.</p>${Object.entries(bands).map(([id,b])=>`<button class="age-choice ${id===state.age?'active':''}" data-age="${id}" aria-pressed="${id===state.age}">${b.name} · Ages ${id}<small>${b.description}</small></button>`).join('')}<p class="reading-level">Preview setting. No birthday or personal details needed.</p>`;d.showModal()}
document.addEventListener('keydown',e=>{if(e.target.id==='question'&&e.key==='Enter'&&!e.shiftKey&&!e.isComposing&&matchMedia('(pointer:fine)').matches){e.preventDefault();e.target.form.requestSubmit()}});
