 if(b.dataset.toggle){state[b.dataset.toggle]=!state[b.dataset.toggle];persist();render(false);return}
 if(b.dataset.option!==undefined&&quizState&&!quizState.checked){quizState.selected=Number(b.dataset.option);render(false);return}
 if(b.dataset.step&&!codeState.running){if(codeState.steps.length>=codeConfig(state.age).max)return toast('Your program is full. Remove a step to try a different move.');codeState.steps.push(b.dataset.step);codeState.message='Ready to test your new program?';render(false);return}
 if(b.dataset.removeStep!==undefined&&!codeState.running){codeState.steps.splice(Number(b.dataset.removeStep),1);render(false);return}
 const action=b.dataset.action,id=b.dataset.id;
 if(action==='ai-preview'){const d=$('#settings');d.innerHTML=`<button class="close" data-action="close-dialog" aria-label="Close AI preview">${I('x')}</button><h2>Zuno AI connection</h2><p>Zuno AI connects automatically when you ask a learning question. Answers, explanations and game hints use the same connection, with wording for ages ${state.age}.</p><p>Zuno AI is powered by ClerkOps. Questions and the selected reading band are processed securely by the AI service. Avoid personal information. Processing services may retain requests for reliability and abuse monitoring for up to 30 days; see privacy details.</p><p>AI answers can be wrong. References and automated review help, but do not replace adult judgement. 40 requests per day per connection, with a shared free-service cap.</p><button class="button" data-action="enable-ai">Reconnect Zuno AI ${I('arrow-right')}</button><a class="text-link" href="#/privacy" data-close-policy>Read privacy details</a>`;d.showModal()}if(action==='enable-ai'){b.disabled=true;b.textContent='Connecting to Zuno AI…';enableAI(state.age).then(()=>{$('#settings').close();render(false);toast('Zuno AI connected.');}).catch(()=>{b.disabled=false;b.textContent='Try connection again';toast('Zuno AI could not connect. Please retry.');})}if(action==='disable-ai'){aiAbort?.abort();aiBusy=false;disableAI();render(false);toast('AI preview off. Library mode is ready.')}if(action==='new-chat'){aiAbort?.abort();aiBusy=false;chatStore.newChat();chatDraft='';if($('#settings').open)$('#settings').close();render(false);$('#question')?.focus();}if(action==='chat-history'){const d=$('#settings');d.innerHTML='<button class="close" data-action="close-dialog" aria-label="Close chat history">'+I('x')+'</button><div class="chat-history-dialog">'+chatHistoryHTML(true)+'</div>';d.showModal()}if(action==='undo-chat'){chatStore.restore(removedChat);removedChat=null;if($('#settings').open)$('#settings').close();render(false)}if(action==='remember-chat'){chatStore.setRemember(!chatStore.remember);render(false)}if(action==='back-top')window.scrollTo({top:0,behavior:reduced()?'instant':'smooth'});if(action==='theme'){const change=()=>{state.theme=state.theme==='light'?'dark':'light';persist();render(false)};document.documentElement.classList.add('theme-reveal');if(document.startViewTransition&&!reduced()){const v=document.startViewTransition(change);v.finished.finally(()=>document.documentElement.classList.remove('theme-reveal'))}else{change();document.documentElement.classList.remove('theme-reveal')}}if(action==='age')ageDialog();if(action==='close-dialog')$('#settings').close();if(action==='read')awardRead(id);
 if(action==='save'){if(state.saved.includes(id))state.saved=state.saved.filter(x=>x!==id);else state.saved.push(id);persist();render(false);toast(state.saved.includes(id)?'Saved in My Universe.':'Removed from saved discoveries.');}
 if(action==='clear-search'){search='';category='all';history.replaceState(null,'','#/discover/library');render(false)}
 if(action==='speak'){if(!('speechSynthesis'in window))return toast('Read-aloud is not available on this browser.');const a=articles.find(a=>a.id===id);if(a){const u=new SpeechSynthesisUtterance(a.title+'. '+a.levels[state.age]+'. '+sectionsFor(a,state.age).map(x=>x.join('. ')).join('. '));u.lang='en-KE';u.rate=.9;speechSynthesis.cancel();speechSynthesis.speak(u);toast('Reading aloud. Change pages to stop.')}}
 if(action==='report'){const d=$('#settings');d.innerHTML=`<button class="close" data-action="close-dialog" aria-label="Close">${I('x')}</button><h2>Thanks for noticing.</h2><p>Please show this story to a trusted grown-up. This preview does not send reports yet. Your observation can help us make the story better.</p><button class="button light" data-action="close-dialog">Got it</button>`;d.showModal()}
 if(action==='check-answer'&&quizState&&quizState.selected!==null&&!quizState.checked){quizState.checked=true;const q=quizState.questions[quizState.index];if(quizState.selected===q.correct)quizState.score++;feedback(quizState.selected===q.correct);render(false);$('.feedback')?.focus()}
 if(action==='next-question'&&quizState?.checked){if(quizState.index===quizFor(quizState.id,state.age,quizzes).questions.length-1){quizState.done=true;quizState.newXP=completeGame(quizState.id)}else{quizState.index++;quizState.selected=null;quizState.checked=false}render(false);$('.quiz-card h1')?.setAttribute('tabindex','-1');$('.quiz-card h1')?.focus()}
