 if(action==='reset-code'&&!codeState.running){codeState={steps:[],pos:codeConfig(state.age).size*(codeConfig(state.age).size-1),running:false};render(false)}if(action==='run-code'&&!codeState.running&&codeState.steps.length)runCode();
 if(action==='orbit-pause'){window.dispatchEvent(new CustomEvent('zuno-orbit-toggle'));const paused=b.dataset.paused!=='true';b.dataset.paused=String(paused);b.innerHTML=I(paused?'play':'pause')+(paused?'Play orbits':'Pause orbits')}
